; >S:RASTER-ROUTINES; PUT "RASTER-ROUTINES";;; THESE ARE THE ROUTINES CALLED; BY THE RASTER IRQ PROGRAMME;;RAST1;; MAIN PLAY AREA - MULTI COLOUR,; STEADY ETC.;;LDA TED+7AND #%11110000ORA #%00001000STA TED+7;; MULTI-COL + 40 COLS; & RESET PIXEL MOVEMENT;;JSR ANIMAT ;* ANIMATE GLOP CHARSJSR RANDOM ;* RNDY NUMBERS;JMP IRQEND;;********************************;RAST2;; PIXEL SCROLLING MESSAGE;; 38 COLS;LDX #7;SHITY;DEX;BPL SHITY;LDA TED+7AND #%11110000 ;*BACK TO 38 COLSORA MESSX      ;*MESSAGE PIX. POS.STA TED+7;JSR MESSVE     ;* GLOP MESSAGEJSR REDJOS     ;* READ I/P DEVICE;LDA STOPBNE MISS1;JSR UPBOMB     ;* BOMB CODEJSR PRNALS     ;* PRINT ALIENSJSR MOVEMN     ;* MOVE BLOB;MISS1;LDA TITLE      ;* ON TITLE PAGE ?BEQ MISS2;JSR BDRGLP     ;* SCROLL BORDER;MISS2;JMP IRQEND;;.END